// ErrPeriodMoved means a renewal lost a race: the subscription is no longer in the period it read, or it was canceled.
var ErrPeriodMoved = errors.New("the subscription's period has moved on")

// PeriodChange moves a subscription to its next period.
type PeriodChange struct {
	From       time.Time // the period the subscription must still be in: it starts here
	Start, End time.Time // the next period
	Invoice    *Invoice  // the invoice of the period to bill, stored in the same step; nil for none
}

// AdvancePeriod moves a subscription to the next period and stores the invoice of that period, if any, in one step. Only
// one caller can move a period on: the others get ErrPeriodMoved and nothing changes. An invoice for a period that already
// has one (same subscription and period start) is refused the same way, so a period is invoiced at most once. It returns the
// subscription and the stored invoice (zero when there is none).
func (s *Store) AdvancePeriod(orgID, subID string, ch PeriodChange, now time.Time) (Subscription, Invoice, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.subs[subID]
	if !ok || old.OrgID != orgID {
		return Subscription{}, Invoice{}, ErrNotFound
	}
	if old.Status == Canceled || !old.CurrentPeriodStart.Equal(ch.From) {
		return Subscription{}, Invoice{}, ErrPeriodMoved
	}
	var inv Invoice
	if ch.Invoice != nil {
		if err := checkInvoice(*ch.Invoice); err != nil {
			return Subscription{}, Invoice{}, err
		}
		if s.hasPeriodInvoiceLocked(subID, ch.Invoice.PeriodStart) {
			return Subscription{}, Invoice{}, ErrPeriodMoved
		}
		var err error
		if inv, err = s.addInvoiceLocked(*ch.Invoice, now); err != nil {
			return Subscription{}, Invoice{}, err
		}
	}
	sub := copySub(old)
	sub.CurrentPeriodStart, sub.CurrentPeriodEnd = ch.Start, ch.End
	s.subs[subID] = sub
	return copySub(sub), inv, nil
}

// hasPeriodInvoiceLocked reports whether the subscription already has an invoice starting its period at start. The caller
// holds s.mu.
func (s *Store) hasPeriodInvoiceLocked(subID string, start *time.Time) bool {
	if start == nil {
		return false
	}
	for _, inv := range s.invoices {
		if inv.SubscriptionID == subID && inv.PeriodStart != nil && inv.PeriodStart.Equal(*start) {
			return true
		}
	}
	return false
}

