// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
// due; a gateway that is unavailable leaves the invoice open and the subscription's status as it was.
//
// RenewDue is safe to run from several servers at once, and again while an earlier run is still going: a period is renewed,
// invoiced and charged by the one call that moves it on, and the others skip it. It goes on with the other subscriptions when
// one fails, and returns the errors after trying them all. RenewDue returns how many subscriptions it renewed or canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	var errs []error
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			return n, errors.Join(append(errs, err)...)
		}
		renewed, err := s.renew(ctx, sub, now)
		if renewed {
			n++
		}
		if err != nil {
