		if plan.UnitAmount > 0 {
			lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
		}
	case store.Metered:
		if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
			lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
		}
	}
	ps, pe := start, end
	return store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
		Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}
}

// pay charges an open invoice to the customer's default payment method. It reports false when the charge was declined. An
// invoice that needs no charge, or whose customer has no payment method, counts as paid here: it stays open and is paid by
// hand. When the gateway is unavailable it returns an error wrapping payments.ErrUnavailable, and nothing was taken.
func (s *Service) pay(ctx context.Context, orgID, invoiceID string) (bool, error) {
	_, _, err := s.Payments.Pay(ctx, orgID, invoiceID, "")
	var decline *payments.DeclineError
	switch {
	case err == nil, errors.Is(err, payments.ErrNoPaymentMethod), errors.Is(err, payments.ErrAlreadyPaid), errors.Is(err, payments.ErrInvoiceVoid):
		return true, nil
	case errors.As(err, &decline):
		return false, nil
	default:
		return false, err
	}
}

func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
	sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.Status = st
		return nil
	})
	if err == nil {
		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	}
	return sub, err
}

func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
	if s.Publisher != nil {
		_ = s.Publisher.Publish(ctx, orgID, typ, data)
	}
}

