func TestRenewDueGoesOnPastAFailure(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	gone := e.CreateCustomer(e.Acme, "Gone", "gone@example.com")
	jane := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	broken, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: gone.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	fine, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: jane.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	if err := e.Store.DeleteCustomer(e.Acme.ID, gone.ID); err != nil {
		t.Fatal(err)
	}
	e.Clock.Set(broken.CurrentPeriodEnd)

	n, err := e.Subs.RenewDue(ctx)
	if !errors.Is(err, store.ErrNotFound) || n != 1 {
		t.Fatalf("RenewDue = %d, %v; want the other subscription renewed and the failure returned", n, err)
	}
	if got, _ := e.Store.Subscription(e.Acme.ID, fine.ID); !got.CurrentPeriodStart.Equal(e.Clock.Now()) {
		t.Fatalf("the other subscription = %+v", got)
	}
	if got, _ := e.Store.Subscription(e.Acme.ID, broken.ID); !got.CurrentPeriodStart.Equal(broken.CurrentPeriodStart) {
		t.Fatalf("the failed subscription moved on: %+v", got)
	}
}

